/**
 * App 里用到的图，全部 base64 内联。
 *
 * 为什么不用 require('*.png')：热更新只替换 JS bundle，安装包里的图片资源不跟着换，
 * 两边的资源编号一旦对不上，图片就整片消失（11/13 踩过一次，启动页立绘那次）。
 * 编进代码里就跟版本无关了。
 * 由 tools/pack-images.py 生成，别手改。
 */

export const avatar = 'data:image/jpeg;base64,';

export const whaleArt = 'data:image/png;base64,';

